package com.alibaba.nacos.console.controller.v3.naming;

import com.alibaba.nacos.api.exception.NacosException;
import com.alibaba.nacos.api.exception.api.NacosApiException;
import com.alibaba.nacos.console.paramcheck.ConsoleDefaultHttpParamExtractor;
import com.alibaba.nacos.console.proxy.naming.InstanceProxy;
import com.alibaba.nacos.console.utils.InstanceFormBuilder;
import com.alibaba.nacos.naming.web.CanDistro;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.verify;

/**
 * Test for {@link ConsoleInstanceController}.
 */
@ExtendWith(MockitoExtension.class)
class ConsoleInstanceControllerTest {

    @Mock
    private InstanceProxy instanceProxy;

    @InjectMocks
    private ConsoleInstanceController controller;

    private InstanceFormBuilder.InstanceFormBuilderBuilder formBuilder;

    @BeforeEach
    void setUp() {
        formBuilder = InstanceFormBuilder.builder()
                .namespaceId("test-namespace")
                .serviceName("test-service")
                .groupName("DEFAULT_GROUP")
                .ip("127.0.0.1")
                .port(8848)
                .clusterName("DEFAULT")
                .ephemeral(false); // persistent by default
    }

    @Test
    void testRemoveInstanceSuccess() throws NacosException {
        // Given
        InstanceForm instanceForm = formBuilder.build();
        doNothing().when(instanceProxy).removeInstance(any(InstanceForm.class), any());

        // When
        var result = controller.removeInstance(instanceForm);

        // Then
        assertEquals("ok", result.getData());
        verify(instanceProxy).removeInstance(any(InstanceForm.class), any());
    }

    @Test
    void testRemoveInstanceWithEphemeralTrueShouldThrow() {
        // Given
        InstanceForm instanceForm = formBuilder.ephemeral(true).build();

        // When & Then
        NacosApiException exception = assertThrows(NacosApiException.class,
                () -> controller.removeInstance(instanceForm));
        assertEquals(HttpStatus.BAD_REQUEST.value(), exception.getErrCode());
        assertEquals("Console only supports deregistering persistent instances", exception.getErrMsg());
    }

    @Test
    void testRemoveInstanceWithEphemeralNullShouldSuccess() throws NacosException {
        // Given: ephemeral is null, which should be treated as persistent (default)
        InstanceForm instanceForm = formBuilder.ephemeral(null).build();
        doNothing().when(instanceProxy).removeInstance(any(InstanceForm.class), any());

        // When
        var result = controller.removeInstance(instanceForm);

        // Then
        assertEquals("ok", result.getData());
        verify(instanceProxy).removeInstance(any(InstanceForm.class), any());
    }

    @Test
    void testRemoveInstanceWhenProxyThrowsNacosException() throws NacosException {
        // Given
        InstanceForm instanceForm = formBuilder.build();
        doThrow(new NacosException(500, "Internal error"))
                .when(instanceProxy).removeInstance(any(InstanceForm.class), any());

        // When & Then
        NacosException exception = assertThrows(NacosException.class,
                () -> controller.removeInstance(instanceForm));
        assertEquals(500, exception.getErrCode());
        assertEquals("Internal error", exception.getErrMsg());
    }

    @Test
    void testRemoveInstanceValidation() {
        // Given: missing required fields
        InstanceForm instanceForm = new InstanceForm();
        instanceForm.setNamespaceId("");
        instanceForm.setServiceName("");

        // When & Then
        NacosApiException exception = assertThrows(NacosApiException.class,
                () -> controller.removeInstance(instanceForm));
        // The validation is done by instanceForm.validate(), which throws NacosApiException
        // We just assert that an exception is thrown.
    }

    // Note: The @CanDistro annotation and TpsControl are not tested here as they are aspect-oriented.
}

InstanceForm instanceForm = new InstanceForm();
instanceForm.setNamespaceId("test-namespace");
instanceForm.setServiceName("test-service");
