import com.alibaba.nacos.naming.core.v2.metadata.ServiceMetadata;
import com.alibaba.nacos.naming.core.v2.pojo.Service;
import com.alibaba.nacos.naming.core.v2.service.impl.PersistentClientOperationServiceImpl;
import com.alibaba.nacos.naming.core.v2.upgrade.UpgradeJudgement;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class CatalogServiceV2ImplTest {

    @Mock
    private ServiceStorage serviceStorage;

    @Mock
    private PersistentClientOperationServiceImpl persistentClientOperationService;

    @Mock
    private UpgradeJudgement upgradeJudgement;

    @InjectMocks
    private CatalogServiceV2Impl catalogServiceV2;

    private static final String NAMESPACE_ID = "test-namespace";
    private static final String GROUP_NAME = "test-group";
    private static final String SERVICE_NAME = "test-service";
    private static final String CLUSTER_NAME = "cluster-hba";
    private static final String DEFAULT_CLUSTER = "DEFAULT";

    private Service service;
    private ServiceInfo serviceInfo;

    @BeforeEach
    void setUp() {
        service = Service.newService(NAMESPACE_ID, GROUP_NAME, SERVICE_NAME);
        serviceInfo = new ServiceInfo();
        serviceInfo.setName(GROUP_NAME + "@@" + SERVICE_NAME);
        serviceInfo.setGroupName(GROUP_NAME);
    }

    @Test
    void testListInstancesWithBlankClusterNameReturnsAll() throws NacosException {
        // Given: clusterName is blank (empty string)
        String blankClusterName = "";

        // Mock service exists
        when(serviceStorage.getService(any(), eq(GROUP_NAME), eq(SERVICE_NAME))).thenReturn(service);

        // Mock service has clusters "cluster-hba" and "cluster-hbb"
        when(serviceStorage.getClusters(service)).thenReturn(new HashSet<>(Arrays.asList("cluster-hba", "cluster-hbb")));

        // Mock service info with instances from different clusters
        Instance instance1 = new Instance();
        instance1.setIp("1.1.1.1");
        instance1.setPort(8080);
        instance1.setClusterName("cluster-hba");

        Instance instance2 = new Instance();
        instance2.setIp("2.2.2.2");
        instance2.setPort(8080);
        instance2.setClusterName("cluster-hbb");

        serviceInfo.setHosts(Arrays.asList(instance1, instance2));
        when(serviceStorage.getData(service)).thenReturn(serviceInfo);

        // When: list instances with blank cluster name
        List<? extends Instance> result = catalogServiceV2.listInstances(NAMESPACE_ID, GROUP_NAME, SERVICE_NAME, blankClusterName, false);

        // Then: should return all instances (both clusters)
        assertEquals(2, result.size());
        // Verify both instances are present
        boolean hasInstance1 = result.stream().anyMatch(inst -> inst.getIp().equals("1.1.1.1") && inst.getClusterName().equals("cluster-hba"));
        boolean hasInstance2 = result.stream().anyMatch(inst -> inst.getIp().equals("2.2.2.2") && inst.getClusterName().equals("cluster-hbb"));
        assertEquals(true, hasInstance1);
        assertEquals(true, hasInstance2);
    }

    @Test
    void testListInstancesWithNullClusterNameReturnsAll() throws NacosException {
        // Given: clusterName is null
        String nullClusterName = null;

        // Mock service exists
        when(serviceStorage.getService(any(), eq(GROUP_NAME), eq(SERVICE_NAME))).thenReturn(service);

        // Mock service has clusters "cluster-hba" and "cluster-hbb"
        when(serviceStorage.getClusters(service)).thenReturn(new HashSet<>(Arrays.asList("cluster-hba", "cluster-hbb")));

        // Mock service info with instances from different clusters
        Instance instance1 = new Instance();
        instance1.setIp("1.1.1.1");
        instance1.setPort(8080);
        instance1.setClusterName("cluster-hba");

        Instance instance2 = new Instance();
        instance2.setIp("2.2.2.2");
        instance2.setPort(8080);
        instance2.setClusterName("cluster-hbb");

