        boolean hasInstance2 = result.stream().anyMatch(inst -> inst.getIp().equals("2.2.2.2") && inst.getClusterName().equals("cluster-hbb"));
        assertEquals(true, hasInstance1);
        assertEquals(true, hasInstance2);
    }

    @Test
    void testListInstancesWithSpecificClusterNameReturnsFilteredInstances() throws NacosException {
        // Given: clusterName is "cluster-hba"

        // Mock service exists
        when(serviceStorage.getService(any(), eq(GROUP_NAME), eq(SERVICE_NAME))).thenReturn(service);

        // Mock service has clusters "cluster-hba" and "cluster-hbb"
        when(serviceStorage.getClusters(service)).thenReturn(new HashSet<>(Arrays.asList("cluster-hba", "cluster-hbb")));

        // Mock service info with instances from different clusters
        Instance instance1 = new Instance();
        instance1.setIp("1.1.1.1");
        instance1.setPort(8080);
        instance1.setClusterName("cluster-hba");

        Instance instance2 = new Instance();
        instance2.setIp("2.2.2.2");
        instance2.setPort(8080);
        instance2.setClusterName("cluster-hbb");

        serviceInfo.setHosts(Arrays.asList(instance1, instance2));
        when(serviceStorage.getData(service)).thenReturn(serviceInfo);

        // When: list instances with specific cluster name
        List<? extends Instance> result = catalogServiceV2.listInstances(NAMESPACE_ID, GROUP_NAME, SERVICE_NAME, CLUSTER_NAME, false);

        // Then: should return only instances from "cluster-hba"
        assertEquals(1, result.size());
        assertEquals("1.1.1.1", result.get(0).getIp());
        assertEquals("cluster-hba", result.get(0).getClusterName());
    }

    @Test
    void testListInstancesThrowsExceptionWhenClusterNotFound() {
        // Given: clusterName is "non-existent-cluster" which doesn't exist in service
        String nonExistentCluster = "non-existent-cluster";

        // Mock service exists
        when(serviceStorage.getService(any(), eq(GROUP_NAME), eq(SERVICE_NAME))).thenReturn(service);

        // Mock service has only "cluster-hba" cluster
        when(serviceStorage.getClusters(service)).thenReturn(new HashSet<>(Collections.singletonList("cluster-hba")));

        // When & Then: should throw NacosException with NOT_FOUND
        NacosException exception = assertThrows(NacosException.class, () -> {
            catalogServiceV2.listInstances(NAMESPACE_ID, GROUP_NAME, SERVICE_NAME, nonExistentCluster, false);
        });

        assertEquals(NacosException.NOT_FOUND, exception.getErrCode());
        assertEquals("cluster " + nonExistentCluster + " is not found!", exception.getErrMsg());
    }

    @Test
    void testListInstancesWithDefaultClusterNameWhenServiceHasDefaultCluster() throws NacosException {
        // Given: clusterName is "DEFAULT" and service has DEFAULT cluster

        // Mock service exists
        when(serviceStorage.getService(any(), eq(GROUP_NAME), eq(SERVICE_NAME))).thenReturn(service);

