        // Mock service info with instances from different clusters
        Instance instance1 = new Instance();
        instance1.setIp("1.1.1.1");
        instance1.setPort(8080);
        instance1.setClusterName(DEFAULT_CLUSTER);

        Instance instance2 = new Instance();
        instance2.setIp("2.2.2.2");
        instance2.setPort(8080);
        instance2.setClusterName("cluster-hba");

        serviceInfo.setHosts(Arrays.asList(instance1, instance2));
        when(serviceStorage.getData(service)).thenReturn(serviceInfo);

        // When: list instances with DEFAULT cluster name
        List<? extends Instance> result = catalogServiceV2.listInstances(NAMESPACE_ID, GROUP_NAME, SERVICE_NAME, DEFAULT_CLUSTER, false);

        // Then: should return only instances from DEFAULT cluster
        assertEquals(1, result.size());
        assertEquals("1.1.1.1", result.get(0).getIp());
        assertEquals(DEFAULT_CLUSTER, result.get(0).getClusterName());
    }

    @Test
    void testListInstancesThrowsExceptionWhenServiceNotFound() {
        // Given: service doesn't exist
        when(serviceStorage.getService(any(), eq(GROUP_NAME), eq(SERVICE_NAME))).thenReturn(null);

