        NacosException exception = assertThrows(NacosException.class, () -> {
            catalogServiceV2.listInstances(NAMESPACE_ID, GROUP_NAME, SERVICE_NAME, CLUSTER_NAME, false);
        });

        assertEquals(NacosException.NOT_FOUND, exception.getErrCode());
        assertEquals(String.format("service %s@@%s is not found!", GROUP_NAME, SERVICE_NAME), exception.getErrMsg());
    }
}

